CREATE TABLE email_accounts(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,config jsonb NOT NULL,imap_secret_id uuid NOT NULL,smtp_secret_id uuid NOT NULL,revision bigint NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT true,last_sync timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id));
CREATE TABLE email_checkpoints(owner_id uuid NOT NULL,account_id uuid NOT NULL,mailbox text NOT NULL,uidvalidity bigint NOT NULL,last_uid bigint NOT NULL DEFAULT 0,rescan_offset bigint NOT NULL DEFAULT 0,PRIMARY KEY(owner_id,account_id,mailbox),FOREIGN KEY(owner_id,account_id) REFERENCES email_accounts(owner_id,id));
CREATE TABLE email_messages(id uuid PRIMARY KEY,owner_id uuid NOT NULL,account_id uuid NOT NULL,mailbox text NOT NULL,uidvalidity bigint NOT NULL,uid bigint NOT NULL,source_key text NOT NULL,message_id text NOT NULL,thread_references jsonb NOT NULL,metadata jsonb NOT NULL,body_text text NOT NULL,attachments jsonb NOT NULL,authentication jsonb NOT NULL DEFAULT '{"spf":"UNKNOWN","dkim":"UNKNOWN","spam":"UNKNOWN","authoritative":false}',privacy_class text NOT NULL DEFAULT 'PRIVATE',trust_level text NOT NULL DEFAULT 'UNTRUSTED_EXTERNAL',received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),UNIQUE(owner_id,account_id,source_key),UNIQUE(owner_id,account_id,mailbox,uidvalidity,uid),FOREIGN KEY(owner_id,account_id) REFERENCES email_accounts(owner_id,id));
CREATE INDEX email_messages_owner ON email_messages(owner_id,account_id,received_at,id);
CREATE TABLE email_drafts(id uuid PRIMARY KEY,owner_id uuid NOT NULL,account_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1,content jsonb NOT NULL,content_digest text NOT NULL,state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN('DRAFT','SUBMITTED','SENT','FAILED','OUTCOME_UNKNOWN')),authorization_id uuid,smtp_evidence jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),FOREIGN KEY(owner_id,account_id) REFERENCES email_accounts(owner_id,id));
CREATE TABLE email_draft_versions(owner_id uuid NOT NULL,draft_id uuid NOT NULL,version bigint NOT NULL,content jsonb NOT NULL,content_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,draft_id,version),FOREIGN KEY(owner_id,draft_id) REFERENCES email_drafts(owner_id,id));
CREATE TABLE email_ingestion_leases(owner_id uuid NOT NULL,account_id uuid NOT NULL,lease_holder uuid,lease_until timestamptz,fence bigint NOT NULL DEFAULT 0,PRIMARY KEY(owner_id,account_id),FOREIGN KEY(owner_id,account_id) REFERENCES email_accounts(owner_id,id));
